#include "unity.h"
#include "buffer.h"
#include "helpers.h"
#include "malloc_wrap.h"

void setUp(void) { }
void tearDown(void) { malloc_reset(); }

void unit_test_buffer_appendf_resize_failure(void) {
    // Setup: create a buffer with some initial content
    buffer_t *buf = helper_create_buffer_with_content("abc");
    TEST_ASSERT_NOT_NULL(buf);

    // Prepare format string and argument
    const char *fmt = "%d";
    int value = 12345;

    // Calculate how many allocations happen before buffer_resize is called
    // helper_create_buffer_with_content("abc") calls buffer_new_with_copy, which calls buffer_new_with_size
    // buffer_new_with_size: 1 malloc (struct) + 1 calloc (data) = 2 allocations
    // buffer_new_with_copy: no extra allocations
    // So, 2 allocations so far

    // buffer_appendf will call buffer_resize, which calls realloc
    // We want the realloc in buffer_resize to fail
    // So, fail after 2 allocations
    malloc_fail_after(2);

    // Test: call buffer_appendf, which should fail due to allocation failure
    int ret = buffer_appendf(buf, fmt, value);
    TEST_ASSERT_EQUAL_INT(-1, ret);

    // The buffer should remain unchanged
    helper_assert_buffer_content(buf, "abc");

    // Cleanup
    helper_free_buffer(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_appendf_resize_failure);
    return UNITY_END();
}


